import {SequenceQuaternionRange} from './sequence-quaternion-range.js';
import {IntervalSelectionIndex} from './sequence-interval-selection.js';
import {SequenceEventIndex} from './sequence-event-index.js';
import {sampleCurveSegment,sampleCurveOutside} from './curve-sampling.js';
import {repeatedSequenceTime} from './sequence-range-time.js';
import {lookupRuntimeObject} from './runtime-object-lookup.js';
import {clampScaleAxis} from './transform-scale.js';
import {Quaternion,Euler,MathUtils} from 'three';
// Assets are captured by the sequence player. Prepare once; seek in O(log n).
export class SequenceSampler{
 constructor(tracks){this.clips=new Map(tracks.filter(t=>['audio','animation'].includes(t.type)).map(t=>[t,new IntervalSelectionIndex(t.clips||[])]));this.eventIndex=new SequenceEventIndex(tracks);this.keys=new Map(tracks.map(t=>[t,this.eventIndex.keys(t)||[...t.keys].sort((a,b)=>a.time-b.time)]));this.rotations=new Map();for(const track of tracks)if(track.type==='rotation'&&track.quaternionInterpolation){this.q??=new Quaternion();this.other??=new Quaternion();this.euler??=new Euler();const keys=this.keys.get(track),values=new Float64Array(keys.length*4);keys.forEach((key,i)=>this.q.setFromEuler(this.euler.set(...key.value.map(MathUtils.degToRad),'XYZ')).toArray(values,i*4));this.rotations.set(track,values);}}
 clip(track,time,metrics){return this.clips.get(track)?.first(time,metrics);}
 clipById(track,id){if(id===undefined)return undefined;this.clipOwners??=new WeakMap();let owner=this.clipOwners.get(track);if(!owner){owner={objects:track.clips};this.clipOwners.set(track,owner);}else owner.objects=track.clips;return lookupRuntimeObject(owner,id);}
 eventRange(track,range){return this.eventIndex.range(track,range);}
 sample(track,time,{discrete=false,reference=false,stable=false}={}){const keys=this.keys.get(track)||[];if(!keys.length)return undefined;discrete||=typeof keys[0].value!=='number'&&!Array.isArray(keys[0].value);if(!reference&&!discrete&&this.rotations.has(track)&&(time<keys[0].time||time>keys.at(-1).time)&&['linear','cycleOffset'].includes(track[time<keys[0].time?'preInfinity':'postInfinity'])){const outside=(this.rotationRange??=new SequenceQuaternionRange()).sample(keys,this.rotations.get(track),time,track);if(outside!==undefined)return outside;}if(!reference&&(discrete||this.rotations.has(track)))time=repeatedSequenceTime(keys,time,track);if(!discrete&&!reference&&!this.rotations.has(track)){const outside=sampleCurveOutside(keys,time,track);if(outside!==undefined)return track.type==='scale'?outside.map(clampScaleAxis):outside;}let lo=0,hi=keys.length;while(lo<hi){const mid=(lo+hi)>>1;if(keys[mid].time<=time)lo=mid+1;else hi=mid;}const first=Math.max(0,lo-1),last=Math.min(lo,keys.length-1),a=keys[first],b=keys[last];if(reference)return lo?a.value:undefined;const copy=()=>stable?a.value:structuredClone(a.value);if(a===b||time<=a.time||discrete||['step','constant'].includes(a.interpolation)||typeof a.value!=='number'&&!Array.isArray(a.value))return copy();const alpha=Math.max(0,Math.min(1,(time-a.time)/(b.time-a.time))),rotations=this.rotations.get(track);if(rotations){this.q.fromArray(rotations,first*4).slerp(this.other.fromArray(rotations,last*4),alpha);this.euler.setFromQuaternion(this.q,'XYZ');return [this.euler.x,this.euler.y,this.euler.z].map(MathUtils.radToDeg);}const value=sampleCurveSegment(keys,first,time);return track.type==='scale'?value.map(clampScaleAxis):value;}
}
